(()=>{'use strict';
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const header=document.querySelector('.site-header'),trigger=document.querySelector('#menu-trigger'),menu=document.querySelector('#site-menu');
 const closeMenu=()=>menu?.close();
 trigger?.addEventListener('click',()=>{menu.showModal();trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-label','Menu sluiten');});
 menu?.querySelector('[data-menu-close]').addEventListener('click',closeMenu);
 menu?.addEventListener('click',e=>{if(e.target===menu){const b=menu.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeMenu();}});
 menu?.addEventListener('close',()=>{trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label','Menu openen');trigger.focus({preventScroll:true});});
 let scheduled=false;const scrolled=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{header?.classList.toggle('is-scrolled',scrollY>12);scheduled=false;});};addEventListener('scroll',scrolled,{passive:true});scrolled();
 function updateHours(){const v={};for(const p of new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Amsterdam',weekday:'long',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()))v[p.type]=p.value;const weekday=v.weekday;const weekend=['Saturday','Sunday'].includes(weekday);const open=weekend?8:7;const close=weekend?15:weekday==='Friday'?21:22;const minute=Number(v.hour)*60+Number(v.minute),on=minute>=open*60&&minute<close*60;let message;if(on)message=`Regulier open tot ${close}:00`;else if(minute<open*60)message=`Regulier open vanaf ${String(open).padStart(2,'0')}:00`;else{const nextWeekend=['Friday','Saturday'].includes(weekday);message=`Morgen vanaf ${nextWeekend?'08':'07'}:00`;}document.querySelectorAll('[data-opening-status]').forEach(el=>{el.textContent=message;el.dataset.open=String(on);});}
 updateHours();setInterval(updateHours,60000);
 if(!reduced&&window.Motion){const {animate,inView}=window.Motion;document.querySelectorAll('[data-reveal]').forEach(el=>inView(el,()=>{animate(el,{opacity:[0,1],y:[18,0]},{duration:.6,ease:[.22,1,.36,1]});},{amount:.08}));const copy=document.querySelector('.p-hero-copy'),frame=document.querySelector('.p-hero-stage');if(copy)animate(copy,{opacity:[0,1],y:[12,0]},{duration:.75,ease:[.22,1,.36,1]});if(frame)animate(frame,{opacity:[0,1],y:[17,0]},{duration:.9,delay:.12,ease:[.22,1,.36,1]});}
 const track=document.querySelector('.gallery-track');document.querySelectorAll('[data-gallery-dir]').forEach(b=>b.addEventListener('click',()=>track?.scrollBy({left:track.clientWidth*.75*Number(b.dataset.galleryDir),behavior:reduced?'instant':'smooth'})));
 const viewer=document.querySelector('#photo-viewer');if(viewer){const items=[...document.querySelectorAll('[data-photo]')];let current=0,returnTo;const large=viewer.querySelector('#photo-large'),figure=viewer.querySelector('.lightbox-photo');const show=i=>{current=(i+items.length)%items.length;const item=items[current],im=item.querySelector('img'),id=item.dataset.photo;large.src=im.src;large.alt=im.alt;figure.classList.toggle('phone',['09','10'].includes(id));figure.style.setProperty('--photo-ratio',id==='09'?'894/1160':'875/1168');document.querySelector('#photo-counter').textContent=`${String(current+1).padStart(2,'0')} / ${items.length} · Absolutely Fit`;document.querySelector('#photo-caption').textContent=item.querySelector('small').textContent;};items.forEach((b,i)=>b.addEventListener('click',()=>{returnTo=b;show(i);viewer.showModal();}));viewer.querySelector('[data-photo-close]').addEventListener('click',()=>viewer.close());viewer.querySelector('[data-photo-prev]').addEventListener('click',()=>show(current-1));viewer.querySelector('[data-photo-next]').addEventListener('click',()=>show(current+1));viewer.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(current-1);}if(e.key==='ArrowRight'){e.preventDefault();show(current+1);}});viewer.addEventListener('close',()=>{large.removeAttribute('src');returnTo?.focus({preventScroll:true});});viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close();}});}
})();
